// English School – valida, limpia y normaliza el lead del formulario de matrícula.
const PROGRAMS = ["Inglés para niños", "Inglés para jóvenes y adultos", "Clases personalizadas"];
const MODES = ['Grupal', 'Personalizada', 'Aún no sé', ''];
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
const clean = (v, max) => String(v ?? '').replace(/[\u0000-\u001f\u007f]/g, ' ').trim().slice(0, max);

const raw = $input.first().json.body ?? $input.first().json;
const headers = $input.first().json.headers ?? {};
const ip = (headers['x-forwarded-for'] || headers['x-real-ip'] || '').split(',')[0].trim() || null;

// Anti-spam: honeypot + tiempo mínimo en página (2.5 s)
const ts = Number(raw.ts);
const spam = !!clean(raw.website_url, 200) || (ts && Date.now() - ts < 2500);

const nombre = clean(raw.name, 80);
const email = clean(raw.email, 120).toLowerCase();
const telefono = clean(raw.phone, 20).replace(/[^\d+()\s-]/g, '');
const programa = clean(raw.program, 60);
const sede = clean(raw.sede, 60);
const modalidad = clean(raw.mode, 20);
const mensajeUsuario = clean(raw.message, 1000);

let error = null;
if (nombre.length < 2) error = 'name';
else if (telefono.replace(/\D/g, '').length < 7) error = 'phone';
else if (email && !EMAIL.test(email)) error = 'email';
else if (!PROGRAMS.includes(programa)) error = 'program';
else if (!sede) error = 'sede';
else if (!MODES.includes(modalidad)) error = 'mode';
else if (!(raw.consent === 'yes' || raw.consent === 'on' || raw.consent === true)) error = 'consent';

let utm = {};
try { const p = JSON.parse(String(raw.utm || '{}')); for (const [k, v] of Object.entries(p)) if (typeof v === 'string') utm[k.slice(0, 30)] = v.slice(0, 500); } catch {}

// Mensaje que ve el asesor en el CRM: sede + tipo de clase + lo que escribió la persona
const mensaje = [`Sede: ${sede}`, modalidad && `Tipo de clase: ${modalidad}`, mensajeUsuario && `Mensaje: ${mensajeUsuario}`].filter(Boolean).join(' · ');

return [{
  json: {
    spam, error, valid: !spam && !error,
    lead: {
      id: $execution.id + '-' + Date.now().toString(36),
      nombre, email: email || null, telefono,
      sede, modalidad,
      servicioInteres: programa,
      leadCalificado: true,
      mensaje,
      mensajeUsuario,
      pagina: clean(raw.page, 200) || '/',
      canal: utm.gclid || utm.gbraid || utm.wbraid ? 'google-ads' : utm.fbclid ? 'meta-ads' : (utm.utm_source || 'organico'),
      gclid: utm.gclid ?? null,
      utm,
      fecha: new Date().toISOString(),
      fechaLocal: new Date().toLocaleString('es-CO', { timeZone: 'America/Bogota', dateStyle: 'full', timeStyle: 'short' }) + ' (Colombia)',
      ip,
      userAgent: clean(raw.userAgent, 300) || null,
      referrer: clean(raw.referrer, 300) || null,
    },
    next: '/gracias/',
  },
}];

