const tpl = (t) => `<tr><td style="padding:0 0 12px"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:${BG};border:1px solid ${LINE};border-radius:12px"><tr><td style="padding:14px 16px"><div style="font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:${NAVY};font-weight:700;margin-bottom:6px">${t.tag}</div><div style="font-size:14px;color:${DEEP};line-height:1.5;margin-bottom:10px">${esc(t.txt)}</div><a href="${wa(t.txt)}" style="display:inline-block;background:#1faa53;color:#fff;font-weight:700;font-size:13px;padding:9px 14px;border-radius:999px;text-decoration:none;font-family:Arial,Helvetica,sans-serif">💬 Enviar por WhatsApp</a></td></tr></table></td></tr>`;
const utm = l.utm || {};
return `<!DOCTYPE html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Nuevo interesado</title></head>
<body style="margin:0;background:${BG};padding:24px 12px;font-family:Arial,Helvetica,sans-serif">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:620px;margin:0 auto;background:#ffffff;border-radius:18px;overflow:hidden;border:1px solid ${LINE}">
  <tr><td style="background:${NAVY};padding:22px 28px">
    <div style="font-family:Georgia,'Times New Roman',serif;font-size:22px;font-weight:700;color:#ffffff">English School</div>
    <div style="font-size:11px;letter-spacing:.28em;text-transform:uppercase;color:#d9dbf2;margin-top:4px">Medellín · Matrículas</div>
  </td></tr>
  <tr><td style="height:6px;font-size:0;background:repeating-linear-gradient(90deg,${RED} 0 24px,#ffffff 24px 48px);background-color:${RED}">&nbsp;</td></tr>
  <tr><td style="padding:24px 28px 6px">
    <span style="display:inline-block;background:${YEL};color:${DEEP};font-size:12px;font-weight:700;border-radius:999px;padding:4px 12px">Nuevo interesado · ${esc(l.fechaLocal)}</span>
    <h1 style="margin:12px 0 4px;font-family:Georgia,'Times New Roman',serif;font-size:26px;color:${DEEP}">${esc(l.nombre)}</h1>
    <div style="color:${MUTED};font-size:15px">${esc(prog)} · ${esc(l.sede)}${l.modalidad ? ' · ' + esc(l.modalidad) : ''}</div>
  </td></tr>
  <tr><td style="padding:16px 28px 6px"><table role="presentation" cellpadding="0" cellspacing="0"><tr>
    ${btn(wa(T[0].txt), '💬 WhatsApp', '#1faa53')}
    ${btn('tel:+' + tel, '📞 Llamar', NAVY)}
    ${btn(mailto, '✉️ Correo prellenado', CTA)}
    ${btn('https://portal.growthdigital.marketing/', '📊 Ver en CRM', DEEP)}
  </tr></table></td></tr>
  <tr><td style="padding:10px 28px 8px"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border:1px solid ${LINE};border-radius:12px;overflow:hidden">
    ${row('Celular', `<a href="tel:+${tel}" style="color:${NAVY};text-decoration:none"><b>${esc(l.telefono)}</b></a>`)}
    ${row('Correo', l.email ? `<a href="mailto:${esc(l.email)}" style="color:${NAVY}">${esc(l.email)}</a>` : '<span style="color:#9a9cb8">No lo dejó</span>')}
    ${row('Programa', esc(prog))}
    ${row('Sede', esc(l.sede))}
    ${row('Tipo de clase', esc(l.modalidad))}
    ${row('Mensaje', esc(l.mensajeUsuario))}
    ${row('Origen', esc(l.canal) + (utm.utm_campaign ? ' · ' + esc(utm.utm_campaign) : ''))}
  </table></td></tr>
  <tr><td style="padding:18px 28px 4px">
    <div style="font-family:Georgia,'Times New Roman',serif;font-size:18px;font-weight:700;color:${DEEP};margin-bottom:4px">Mensajes listos para cerrar la matrícula</div>
    <div style="font-size:13px;color:${MUTED};margin-bottom:12px">Un clic abre WhatsApp con el mensaje escrito. Úsalos en orden si no responde.</div>
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0">${T.map(tpl).join('')}</table>
